def filterCharacters(s: str, k: int) -> str:
    # 1. Count frequency of each character in the whole string
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1

    # 2. Keep characters whose total frequency is strictly less than k, in original order
    result = []
    for ch in s:
        if freq[ch] < k:
            result.append(ch)

    return ''.join(result)
